export {
  switchButtonClassName as shadcnSwitchButtonClassName,
  switchDescriptionClassName as shadcnSwitchDescriptionClassName,
  switchKnob as shadcnSwitchKnob,
  switchLabelClassName as shadcnSwitchLabelClassName,
  switchRowClassName as shadcnSwitchRowClassName,
  switchTextClassName as shadcnSwitchTextClassName,
} from "../switch/view";

import { describe, expect, test } from "vitest";

import * as Switch from "./index";

describe("shadcn Switch registry view", () => {
  test("reuses the Foldkit Switch functional contract", () => {
    expect(Switch.init).toBeTypeOf("function");
    expect(Switch.update).toBeTypeOf("function");
    expect(Switch.view).toBeTypeOf("function");
    expect(Switch.shadcnSwitchButtonClassName).toContain("data-[checked]");
  });
});
